const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const builtins=[{id:'brown',title:'夜色里的低语',scene:'睡眠',type:'local',desc:'柔和棕噪音 · 本地合成',icon:'☾'},{id:'pink',title:'风经过窗边',scene:'放松',type:'local',desc:'轻柔滤波噪音 · 本地合成',icon:'≈'},{id:'white',title:'留白的午后',scene:'专注',type:'local',desc:'均匀白噪音 · 本地合成',icon:'◌'}];
let saved=[];try{saved=JSON.parse(window.murmurStore.getItem('murmur-sounds')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(x=>x&&typeof x.title==='string'&&typeof x.url==='string'&&/^https?:\/\//i.test(x.url))}catch{}let page='home',filter='全部',query='',soundType='全部',current=null,playing=false,ctx,source,gain,endAt=0,volume=.35;
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(notify.t);notify.t=setTimeout(()=>$('#toast').style.display='none',3000)}
function persist(){try{window.murmurStore.setItem('murmur-sounds',JSON.stringify(saved));return true}catch{notify('设备存储不可用，暂时无法保存');return false}}
function all(){return [...builtins,...saved]}function cards(items){return items.length?items.map(s=>`<article class="sound"><div class="art">${esc(s.icon||'↗')}</div><button class="sound-info" data-sound="${esc(s.id)}"><strong>${esc(s.title)}</strong><small>${esc(s.scene)} · ${esc(s.type==='local'?s.desc:'外部收藏 · 原平台收听')}</small></button><button class="play" data-sound="${esc(s.id)}" aria-label="打开${esc(s.title)}">${s.type==='local'?'▷':'↗'}</button>${s.type==='external'?`<button class="delete" data-delete="${esc(s.id)}" aria-label="删除${esc(s.title)}">×</button>`:''}</article>`).join(''):'<div class="empty"><p>没有符合条件的声音</p><button class="pill" data-reset>清除筛选</button></div>'}
const soundTypes=['全部','人声','触发音','环境音','视觉','其他'];
function typesFor(s){if(s.type==='local')return ['环境音'];const title=s.title;const tags=[];if(/耳语|轻语|人声|说话|聊天|哄睡|角色|检查|医疗|praise|good boy|good girl|whisper|roleplay/i.test(title))tags.push('人声');if(/敲|触发|掏耳|采耳|刷|摩擦|按摩|揉|抓|刮|咀嚼|口腔|口音|tapping|scratch|trigger|mouth/i.test(title))tags.push('触发音');if(/雨声|风声|海浪|流水|白噪|棕噪|环境音|壁炉|篝火|森林|rain|ocean|ambient/i.test(title))tags.push('环境音');if(/视觉|涂色|手势|镜头|屏幕|光线|灯光|visual|hand movement/i.test(title))tags.push('视觉');return tags.length?tags:['其他']}
function subfilters(){return '<div class="type-filters" role="group" aria-label="声音类型">'+soundTypes.map(t=>'<button data-type="'+t+'" aria-pressed="'+(soundType===t)+'" class="'+(soundType===t?'active':'')+'">'+t+'</button>').join('')+'</div>'}
let customScenes=[];
try{const rows=JSON.parse(window.murmurStore.getItem('murmur-scenes')||'[]');if(Array.isArray(rows))customScenes=rows.filter(s=>s&&typeof s.name==='string'&&Array.isArray(s.soundIds)).map(s=>({...s,soundIds:s.soundIds.filter(id=>typeof id==='string')}))}catch{}
function sceneNames(){return ['睡眠','专注','放松',...customScenes.map(s=>s.name)]}
function matchesScene(sound,name){const custom=customScenes.find(s=>s.name===name);return name==='全部'||(custom?custom.soundIds.includes(sound.id):sound.scene===name)}
function sceneCards(){return [['☾','睡眠'],['◌','专注'],['≈','放松'],...customScenes.map(s=>['◇',s.name])].map(([i,t])=>'<button class="scene" data-scene="'+esc(t)+'"><b aria-hidden="true">'+i+'</b><strong>'+esc(t)+'</strong><span class="scene-arrow" aria-hidden="true">↗</span></button>').join('')+'<button class="scene new-scene" data-new-scene><b aria-hidden="true">＋</b><strong>添加新场景</strong></button>'}
function saveScene(name,soundIds){name=name.trim();if(!name)return '请输入场景名称';if(name.length>20)return '场景名称最多 20 个字';if(['全部',...sceneNames()].includes(name))return '已有同名场景，请换一个名称';const valid=new Set(all().map(s=>s.id));const next=[...customScenes,{id:'scene-'+Date.now(),name,soundIds:[...new Set(soundIds)].filter(id=>valid.has(id))}];try{window.murmurStore.setItem('murmur-scenes',JSON.stringify(next));customScenes=next;return ''}catch{return '无法保存，请检查浏览器存储后重试'}}
function openSceneForm(){let d=$('#sceneDialog');if(!d){d=document.createElement('dialog');d.id='sceneDialog';d.innerHTML='<form id="sceneForm"><div class="sheet-head"><h2>新建场景</h2><button type="button" data-close="sceneDialog" aria-label="关闭">×</button></div><label>场景名称<input id="sceneName" required maxlength="20" placeholder="例如：瑜伽、通勤、泡澡"></label><div class="picker-heading"><span>加入声音 · 可选</span><span id="selectionCount">已选 0 条</span></div><input id="sceneSearch" type="search" aria-label="搜索已有声音" placeholder="搜索声音库…"><div id="scenePicker"></div><p id="sceneError" role="alert"></p><div class="scene-actions"><button type="button" id="createEmpty">暂不选择，创建场景</button><button type="submit" class="primary">创建场景</button></div></form>';document.body.append(d)}$('#sceneForm').reset();$('#sceneError').textContent='';let picked=new Set();function list(){const q=$('#sceneSearch').value.trim().toLowerCase();const items=all().filter(s=>s.title.toLowerCase().includes(q));$('#scenePicker').innerHTML=items.length?items.map(s=>'<label class="picker-row"><input type="checkbox" value="'+esc(s.id)+'" '+(picked.has(s.id)?'checked':'')+'><span>'+esc(s.title)+'</span></label>').join(''):'<p class="picker-empty">没有匹配的声音</p>';$('#selectionCount').textContent='已选 '+picked.size+' 条'}$('#scenePicker').onchange=e=>{if(e.target.type!=='checkbox')return;if(e.target.checked)picked.add(e.target.value);else picked.delete(e.target.value);$('#selectionCount').textContent='已选 '+picked.size+' 条'};$('#sceneSearch').oninput=list;function commit(ids){const error=saveScene($('#sceneName').value,ids);if(error){$('#sceneError').textContent=error;return}d.close();render();notify('场景已创建')}$('#sceneForm').onsubmit=e=>{e.preventDefault();commit([...picked])};$('#createEmpty').onclick=()=>commit([]);list();d.showModal()}

let relaxedSeconds=0,usageAudioTime=null,usageSavedAt=0;
try{const n=Number(window.murmurStore.getItem('murmur-relaxed-seconds')||0);if(Number.isFinite(n)&&n>=0)relaxedSeconds=n}catch{}
function usageText(){if(relaxedSeconds<60)return '您已放松 '+Math.floor(relaxedSeconds)+' 秒';if(relaxedSeconds<3600)return '您已放松 '+Math.floor(relaxedSeconds/60)+' 分钟';return '您已放松 '+(Math.floor(relaxedSeconds/360)/10).toLocaleString('zh-CN',{maximumFractionDigits:1})+' 小时'}
function usageMarkup(){return '<section class="usage-summary" aria-label="累计放松时长"><span class="usage-mark" aria-hidden="true">◷</span><div><p id="usageTotal">'+usageText()+'</p><small>累计在 Murmur 内收听的时间</small></div></section>'}
function recordUsage(force=false){if(playing&&ctx&&usageAudioTime!==null){const now=ctx.currentTime;const delta=now-usageAudioTime;if(Number.isFinite(delta)&&delta>0)relaxedSeconds+=delta;usageAudioTime=now}const label=$('#usageTotal');if(label)label.textContent=usageText();if(force||Date.now()-usageSavedAt>=5000){try{window.murmurStore.setItem('murmur-relaxed-seconds',String(relaxedSeconds));usageSavedAt=Date.now()}catch{}}}
setInterval(()=>recordUsage(),1000);
window.addEventListener('pagehide',()=>recordUsage(true));
document.addEventListener('visibilitychange',()=>recordUsage(true));
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const m=$('#main');$('#addTop').setAttribute('aria-label',page==='home'?'添加新场景':'添加声音链接');if(page==='home'){m.innerHTML=usageMarkup()+'<div class="scenes" aria-label="选择场景">'+sceneCards()+'</div>'}else{m.innerHTML='<input class="search" id="search" aria-label="搜索声音" placeholder="搜索声音…" value="'+esc(query)+'"><div class="filters">'+['全部',...sceneNames()].map(t=>'<button data-filter="'+esc(t)+'" class="'+(filter===t?'active':'')+'">'+esc(t)+'</button>').join('')+'</div>'+subfilters()+'<div class="sound-list" id="results">'+libraryCards()+'</div>';$('#search').oninput=e=>{query=e.target.value;$('#results').innerHTML=libraryCards()}}}
function libraryCards(){return cards(all().filter(x=>matchesScene(x,filter)&&(soundType==='全部'||typesFor(x).includes(soundType))&&x.title.toLowerCase().includes(query.toLowerCase())))}
function halt(){recordUsage(true);usageAudioTime=null;if(source){try{source.stop()}catch{}source.disconnect();source=null}playing=false;updatePlayer()}
async function start(){if(!current||current.type!=='local')return;try{ctx??=new (window.AudioContext||window.webkitAudioContext)();await ctx.resume();const len=ctx.sampleRate*8,buffer=ctx.createBuffer(1,len,ctx.sampleRate),data=buffer.getChannelData(0);let brown=0;for(let i=0;i<len;i++){const n=Math.random()*2-1;brown=(brown+.02*n)/1.02;data[i]=current.id==='brown'?brown*3.5:current.id==='pink'?brown*2+n*.12:n*.3}source=ctx.createBufferSource();source.buffer=buffer;source.loop=true;gain=ctx.createGain();gain.gain.setValueAtTime(0,ctx.currentTime);gain.gain.linearRampToValueAtTime(volume,ctx.currentTime+1);source.connect(gain);gain.connect(ctx.destination);source.start();usageAudioTime=ctx.currentTime;playing=true;updatePlayer()}catch{notify('声音暂时无法启动，请再次点击播放');halt()}}
function updatePlayer(){if(!current)return;$('#mini').hidden=false;$('#mini').innerHTML=`<div class="art">${esc(current.icon||'↗')}</div><button class="mini-open" data-expand>${esc(current.title)}<small>${current.type==='external'?'外部收藏 · 原平台收听':playing?'正在播放 · 本地合成':'已暂停 · 本地合成'}</small></button><button class="play" ${current.type==='local'?'data-toggle':'data-expand'} aria-label="${playing?'暂停':'打开播放页'}">${current.type==='external'?'↗':playing?'Ⅱ':'▷'}</button>`;$('#playerTitle').textContent=current.title;$('#playerStatus').textContent=current.type==='external'?'外部收藏 · 播放状态由原平台管理':playing?'正在播放 · 慢慢呼吸':'已暂停';$('#controls').hidden=current.type!=='local';$('#external').hidden=current.type!=='external';if(current.type==='external')$('#external').href=current.url;$('#toggle').textContent=playing?'暂停':'继续播放';$('#playerNote').textContent=current.type==='external'?'返回 Murmur 后能否继续收听，取决于原平台。这里无法控制原平台进度、音量或定时停止。':'内置环境底噪由本地合成。定时结束前 10 秒渐弱；锁屏或后台时的表现受浏览器限制。'}
document.addEventListener('click',async e=>{let b=e.target.closest('button,a');if(!b)return;if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0)}if(b.hasAttribute('data-library')){page='library';filter='全部';render();window.scrollTo(0,0)}if(b.dataset.scene){page='library';filter=b.dataset.scene;soundType='全部';query='';render();window.scrollTo(0,0)}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.type){soundType=b.dataset.type;render()}if(b.hasAttribute('data-reset')){filter='全部';soundType='全部';query='';render()}if(b.hasAttribute('data-new-scene')||(b.id==='addTop'&&page==='home')){openSceneForm()}if(b.hasAttribute('data-add')||(b.id==='addTop'&&page!=='home')){$('#formError').textContent='';$('#add').showModal()}if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.sound){const next=all().find(s=>s.id===b.dataset.sound);if(!next)return;if(current?.id!==next.id){halt();endAt=0;$('#timer').value='0';current=next}updatePlayer();$('#player').showModal();if(current.type==='local'&&!playing)await start()}if(b.hasAttribute('data-expand'))$('#player').showModal();if(b.hasAttribute('data-toggle')||b.id==='toggle'){if(playing)halt();else await start()}if(b.dataset.delete){let idx=saved.findIndex(s=>s.id===b.dataset.delete);if(idx<0)return;const old=[...saved];saved.splice(idx,1);if(!persist()){saved=old;return}if(current?.id===b.dataset.delete){halt();current=null;$('#mini').hidden=true}render();notify('已移除收藏')}});
$('#addForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let url;try{url=new URL(f.get('url'));if(!['http:','https:'].includes(url.protocol))throw Error()}catch{$('#formError').textContent='请填写有效的 http 或 https 链接';return}if(saved.some(s=>s.url===url.href)){$('#formError').textContent='这个链接已经在声音库里了';return}const title=f.get('title').trim();if(!title){$('#formError').textContent='请填写声音名称';return}saved.push({id:'saved-'+Date.now(),title,url:url.href,scene:f.get('scene'),type:'external',icon:'↗'});if(!persist()){saved.pop();return}e.target.reset();$('#add').close();render();notify('已收藏，喜欢的声音不会散落了')};
$('#volume').oninput=e=>{volume=Number(e.target.value);if(gain&&playing)gain.gain.setTargetAtTime(volume,ctx.currentTime,.1)};$('#timer').onchange=e=>{endAt=Number(e.target.value)?Date.now()+Number(e.target.value)*60000:0;if(gain&&playing)gain.gain.setTargetAtTime(volume,ctx.currentTime,.2)};
setInterval(()=>{if(!endAt){$('#timerStatus').textContent='';return}let left=endAt-Date.now();if(left<=0){halt();endAt=0;$('#timer').value='0';$('#timerStatus').textContent='定时已结束';return}$('#timerStatus').textContent=`${Math.ceil(left/60000)} 分钟后停止`;if(left<10000&&playing&&gain)gain.gain.setTargetAtTime(volume*left/10000,ctx.currentTime,.2)},500);render();
